package ama.storage;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.math.BigInteger;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Strict test-owned normalization of the two existing product wires; never a capability. */
public final class Task11B3LocalDecision {
 private static final ObjectMapper JSON=new ObjectMapper();
 private static final Set<String> SNAKE=Set.of("task_id","publication_id","submission_no","confirmation_id","provider_id","library_id","folder_id","local_state","local_reason","local_decided_by","local_attempt_no","local_execution_id","local_decided_at"),CAMEL=Set.of("localState","reason","decidedAt","decidedBy","attemptNoToken","executionId");
 public record Binding(String task,String publication,String confirmation,String provider,String library,String folder,String owner,String execution,String submissionNo){}
 static String text(JsonNode row,String key){assertTrue(row.path(key).isTextual(),key+" must be text");String value=row.get(key).textValue();assertFalse(value.isBlank(),key+" must be present");return value;}
 static Set<String> fields(JsonNode value){assertTrue(value.isObject());var names=new HashSet<String>();value.fieldNames().forEachRemaining(names::add);return names;}
 static String ordinal(JsonNode n){assertTrue(n.isIntegralNumber(),"Integral ordinal required");BigInteger v=n.bigIntegerValue();assertTrue(v.signum()>=0&&v.compareTo(BigInteger.valueOf(Long.MAX_VALUE-1))<=0);return v.toString();}
 public static Binding binding(JsonNode row,String owner,String execution){String submission=ordinal(row.path("submission_no"));assertEquals("3",submission);return new Binding(text(row,"task_id"),text(row,"publication_id"),text(row,"confirmation_id"),text(row,"provider_id"),text(row,"library_id"),text(row,"folder_id"),owner,execution,submission);}
 static String time(String value){assertTrue(value.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}(?:T[0-9]{2}:[0-9]{2}(?::[0-9]{2}(?:\\.[0-9]{1,6})?)?| [0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]{1,6})?)"),"Exact UTC SQL/local ISO microsecond time required");try{return LocalDateTime.parse(value.replace(' ','T')).toString();}catch(java.time.format.DateTimeParseException invalid){throw new AssertionError("Invalid decision time",invalid);}}
 public static JsonNode fromSealedRow(JsonNode row,Binding binding){var response=JSON.createObjectNode().put("taskId",binding.task()).put("httpStatus",200);var d=JSON.createObjectNode();for(String field:SNAKE){assertTrue(row.has(field),"Actual sealed row field missing: "+field);d.set(field,row.get(field));}response.set("decision",d);return normalize(response,binding);}
 public static JsonNode normalize(JsonNode response,Binding binding){
  assertTrue(response.isObject());assertEquals(binding.task(),text(response,"taskId"));assertTrue(response.path("httpStatus").isIntegralNumber());assertEquals(BigInteger.valueOf(200),response.get("httpStatus").bigIntegerValue());JsonNode d=response.path("decision");boolean snake=d.has("local_state");assertEquals(snake?SNAKE:CAMEL,fields(d),"Exact supported decision wire fields required");
  if(snake){assertEquals(binding.task(),text(d,"task_id"));assertEquals(binding.publication(),text(d,"publication_id"));assertEquals(binding.confirmation(),text(d,"confirmation_id"));assertEquals(binding.provider(),text(d,"provider_id"));assertEquals(binding.library(),text(d,"library_id"));assertEquals(binding.folder(),text(d,"folder_id"));assertEquals(binding.submissionNo(),ordinal(d.path("submission_no")));}
  else{assertEquals(binding.publication(),text(response,"publicationId"));assertEquals(binding.confirmation(),text(response,"confirmationId"));assertEquals(binding.provider(),text(response,"providerId"));assertEquals(binding.library(),text(response,"libraryId"));assertEquals(binding.folder(),text(response,"folderId"));assertEquals(binding.submissionNo(),text(response,"submissionNoToken"));}
  String state=text(d,snake?"local_state":"localState"),reason=text(d,snake?"local_reason":"reason"),owner=text(d,snake?"local_decided_by":"decidedBy"),execution=text(d,snake?"local_execution_id":"executionId"),attempt=snake?ordinal(d.path("local_attempt_no")):text(d,"attemptNoToken"),at=time(text(d,snake?"local_decided_at":"decidedAt"));
  assertEquals("NEVER_MARKED",state);assertEquals("EXPIRED_UNMARKED_ABANDONED",reason);assertEquals(binding.owner(),owner);assertEquals(binding.execution(),execution);assertEquals("0",attempt,"READY0 decision requires exact lossless attempt0");
  return JSON.createObjectNode().put("localState",state).put("reason",reason).put("decidedAt",at).put("decidedBy",owner).put("attemptNoToken",attempt).put("executionId",execution);
 }
}